  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Healthcare Study Hub</title>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&amp;family=Fraunces:wght@600;700&amp;display=swap" rel="stylesheet">
  <style>
:root{--ink:#382534;--berry:#752e50;--rose:#a34168;--blush:#fcecf1;--muted:#695663;--line:#ead8df;--success:#255e49;--error:#973d43}
*{box-sizing:border-box}body{margin:0;color:var(--ink);font-family:"DM Sans",sans-serif}
.app-shell{width:100%;min-height:calc(100 * min(var(--vh, 1vh), 1vh));display:flex}
.side{width:242px;flex:none;background:#54283f;color:white;padding:30px 17px;display:flex;flex-direction:column;gap:34px}
.brand{display:flex;align-items:center;gap:11px;font-weight:800;letter-spacing:-.03em;font-size:19px;padding:0 10px}
.brand-icon{background:#af5376;border-radius:13px;padding:9px;display:flex}
.nav-list{display:flex;flex-direction:column;gap:5px}
.nav-btn{width:100%;display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:12px;text-align:left;color:#f3dce6;font-weight:600;transition:.2s}
.nav-btn:hover,.nav-btn.active{background:#ffffff21;color:white}.nav-btn.active{box-shadow:inset 3px 0 #f4adc6}
.nav-btn svg{width:18px;height:18px;flex:none}
.workspace{min-width:0;flex:1;padding:32px clamp(18px,4vw,58px) 55px}
.page-width{max-width:1200px;margin:0 auto}
.eyebrow{text-transform:uppercase;letter-spacing:.16em;color:var(--berry);font-size:11px;font-weight:800}
h1,h2,h3{letter-spacing:-.035em}h1{font-family:Fraunces,serif;line-height:1.16}h2{font-weight:800}h3{font-weight:700}
.panel{background:white;border:1px solid var(--line);border-radius:20px;box-shadow:0 8px 30px #713c5110}
.hero{background:#fae7ee;border-radius:25px;overflow:hidden;display:grid;grid-template-columns:1.35fr .8fr;min-height:205px}
.hero img{width:100%;height:100%;max-height:265px;object-fit:cover}
.metric{padding:20px;min-height:122px;border-top:3px solid #e8afc2}.metric strong{display:block;font-size:30px;letter-spacing:-.05em;margin-top:12px;color:var(--berry)}
.pill{background:var(--blush);color:var(--berry);padding:6px 11px;border-radius:100px;font-size:12px;font-weight:700}
.action{background:var(--berry);color:white;padding:11px 17px;border-radius:11px;font-weight:700;transition:.2s}
.action:hover{background:#5d203e}.secondary{background:#f9e7ed;color:#71304e;padding:10px 15px;border-radius:11px;font-weight:700}
.secondary:hover{background:#f1d4df}.danger{color:#963943;background:#fff0f1}.danger:hover{background:#ffe0e3}
button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #b34b75;outline-offset:3px}
input,select,textarea{border:1px solid #dec6d0;border-radius:11px;background:white;padding:11px 13px;width:100%;color:var(--ink)}
label{font-weight:700}.small-copy{font-size:13px;color:#614e5c;line-height:1.55}.muted{color:var(--muted)}
.topic-card{padding:22px;display:flex;flex-direction:column;gap:12px}.topic-card:hover{border-color:#d792ac}
.flip-scene{perspective:1000px;height:245px;cursor:pointer}.flip-inner{height:100%;position:relative;transition:transform .55s;transform-style:preserve-3d}
.flip-scene.flipped .flip-inner{transform:rotateY(180deg)}.flip-face{position:absolute;inset:0;backface-visibility:hidden;border-radius:22px;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:30px}
.flip-back{transform:rotateY(180deg);background:#54283f;color:white}.flip-front{background:#faeaf0;border:1px solid #e4b9ca}
.flip-back .eyebrow{color:#ffd4e4}
.answer{display:block;width:100%;text-align:left;background:white;border:1px solid var(--line);border-radius:12px;padding:13px 16px;margin-top:9px}
.answer:hover:not(:disabled){border-color:var(--rose);background:#fff5f8}.answer.correct{background:#e8f5ed;border-color:#398665;color:#20543e}.answer.wrong{background:#fff0f1;border-color:#d77e87;color:#842e38}
.view[hidden],.hidden-force{display:none!important}
#feedback:not(:empty){padding:12px 16px;border-radius:12px;background:#e8f5ed;color:#20543e;margin-bottom:18px}#feedback.error{background:#fff0f1;color:#842e38}
.check-row{display:flex;align-items:center;gap:14px;padding:13px 5px;border-bottom:1px solid var(--line);cursor:pointer}.check-row:last-child{border:0}
.check-row input{width:21px;height:21px;accent-color:var(--berry);flex:none}.check-row:has(input:checked) span{text-decoration:line-through;color:var(--muted)}
.track{height:10px;background:#f2dce5;border-radius:100px;overflow:hidden}.fill{height:100%;background:#a34168;border-radius:100px;transition:width .25s}
.cup{width:48px;height:52px;display:grid;place-items:center;border:1px solid #dfb8c8;border-radius:12px;background:#fff3f7;color:#78465d;transition:.2s}
.cup svg{width:23px;height:23px}.cup.filled{background:#752e50;color:white;border-color:#752e50}.cup:hover{transform:translateY(-2px)}
.guidance-accent{border-left:4px solid #a34168!important}
#quiz-explanation{background:#fcecf1;color:#51263c}
#missed-list .review-item{background:#fff5f8}
.history-line{border-bottom:1px solid #f0e1e7}
@media(max-width:800px){.app-shell{display:block}.side{width:100%;padding:13px 16px;gap:12px}.brand{font-size:17px}.nav-list{flex-direction:row;overflow-x:auto;padding-bottom:3px}.nav-btn{width:auto;white-space:nowrap;padding:9px 11px;font-size:13px}.nav-btn svg{width:16px;height:16px}.workspace{padding:23px 17px 45px}.hero{grid-template-columns:1fr}.hero img{height:155px;max-height:none}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
</style>
