     <section id="blood-pressure" class="view" hidden="" aria-labelledby="bp-title">
      <p data-template-id="bp-eyebrow" class="canva-text eyebrow mb-2" style="color: rgb(117, 46, 80); font-weight: 400; font-style: normal; font-size: 16px;">Personal learning record</p>
      <h1 id="bp-title" data-template-id="bp-title" class="canva-text mb-2" style="color: rgb(56, 37, 52); font-weight: 700; font-style: normal; font-size: 32px;">Blood pressure journal.</h1>
      <p data-template-id="bp-intro" class="canva-text muted mb-5" style="color: rgb(105, 86, 99); font-weight: 400; font-style: normal; font-size: 16px;">Record readings to practice understanding measurements and keep a personal history.</p>
      <div class="panel guidance-accent p-5 mb-5 max-w-3xl">
       <h2 data-template-id="bp-guidance-title" class="canva-text mb-2" style="color: rgb(56, 37, 52); font-weight: 800; font-style: normal; font-size: 24px;">A learning tool, not a diagnosis</h2>
       <p data-template-id="bp-guidance" class="canva-text small-copy" style="color: rgb(97, 78, 92); font-weight: 400; font-style: normal; font-size: 16px;">This record is for learning and personal record-keeping only, not diagnosis or treatment. Follow proper measurement guidance, and consult a qualified healthcare professional if you have concerns. Do not enter identifiable patient information.</p>
      </div>
      <form id="bp-form" class="panel p-5 md:p-7 max-w-3xl mb-6">
       <h2 data-template-id="bp-form-title" class="canva-text mb-4" style="color: rgb(56, 37, 52); font-weight: 800; font-style: normal; font-size: 24px;">Record a reading</h2>
       <div class="grid sm:grid-cols-3 gap-4 mb-4">
        <div>
         <label data-template-id="bp-systolic-label" class="canva-text block mb-2" for="bp-systolic" style="color: rgb(56, 37, 52); font-weight: 700; font-style: normal; font-size: 16px;">Systolic (mmHg)</label><input id="bp-systolic" type="number" min="1" max="350" step="1" inputmode="numeric" required="">
        </div>
        <div>
         <label data-template-id="bp-diastolic-label" class="canva-text block mb-2" for="bp-diastolic" style="color: rgb(56, 37, 52); font-weight: 700; font-style: normal; font-size: 16px;">Diastolic (mmHg)</label><input id="bp-diastolic" type="number" min="1" max="250" step="1" inputmode="numeric" required="">
        </div>
        <div>
         <label data-template-id="bp-pulse-label" class="canva-text block mb-2" for="bp-pulse" style="color: rgb(56, 37, 52); font-weight: 700; font-style: normal; font-size: 16px;">Pulse (beats/min)</label><input id="bp-pulse" type="number" min="1" max="300" step="1" inputmode="numeric" required="">
        </div>
       </div><label data-template-id="bp-date-label" class="canva-text block mb-2" for="bp-date" style="color: rgb(56, 37, 52); font-weight: 700; font-style: normal; font-size: 16px;">Date and time</label><input id="bp-date" class="mb-4" type="datetime-local" required=""><label data-template-id="bp-notes-label" class="canva-text block mb-2" for="bp-notes" style="color: rgb(56, 37, 52); font-weight: 700; font-style: normal; font-size: 16px;">Notes (optional)</label><textarea id="bp-notes" rows="3" maxlength="1000" placeholder="Measurement context or study observations"></textarea>
