<script>
// MySQL/PHP adapter for this app. All persistence goes through api.php.
window.dataSdk = (() => {
  let handler = null;
  async function request(action, payload = {}) {
    const response = await fetch('api.php?action=' + encodeURIComponent(action), {
      method: action === 'list' ? 'GET' : 'POST',
      headers: {'Content-Type': 'application/json'},
      body: action === 'list' ? undefined : JSON.stringify(payload)
    });
    const result = await response.json();
    if (!response.ok || result.error) throw new Error(result.error || 'Request failed');
    return result;
  }
  async function refresh() {
    const result = await request('list');
    handler?.onDataChanged(result.data || []);
  }
  return {
    async init(callback) {
      handler = callback;
      try { await refresh(); return {isOk: true}; }
      catch (error) { console.error(error); return {isOk: false}; }
    },
    async create(data) {
      try { await request('create', {data}); await refresh(); return {isOk: true}; }
      catch (error) { console.error(error); return {isOk: false}; }
    },
    async update(data) {
      try { await request('update', {data}); await refresh(); return {isOk: true}; }
      catch (error) { console.error(error); return {isOk: false}; }
    },
    async delete(data) {
      try { await request('delete', {id: data.__backendId}); await refresh(); return {isOk: true}; }
      catch (error) { console.error(error); return {isOk: false}; }
    }
  };
})();
</script>

  <script>
(() => {
