    {q:'Which concept supports protecting private patient information?',options:['Confidentiality','Absorption','Homeostasis'],answer:0,why:'Confidentiality concerns safeguarding private information.'},
    {q:'What is teach-back used to explore?',options:['Medicine dosage','Understanding of information','A diagnosis'],answer:1,why:'Teach-back checks whether information was understood; it is not a diagnostic technique.'},
    {q:'Which item is commonly described as a vital sign?',options:['Hair color','Pulse','Height'],answer:1,why:'Pulse is one commonly observed vital sign.'},
    {q:'What is a foundational infection-prevention topic?',options:['Hand hygiene','Word roots','Body structure'],answer:0,why:'Hand hygiene is a fundamental topic in preventing transmission.'},
    {q:'In pharmacology, what does “route” refer to?',options:['A drug’s brand','How a medicine enters the body','The patient’s address'],answer:1,why:'Route names the way a medicine enters the body. It does not specify which route to use.'}
  ];
  let records=[],ready=false,loadTimer,flashOrder=cards.map((_,i)=>i),flashIndex=0,quizIndex=0,quizScore=0,missed=[],answered=false,noteEdit=null,bpEdit=null,streakBusy=false;
  let pendingDaily=null,dailyQueue=Promise.resolve(),lastDailyCall=0;
