  function show(view){document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==view);document.querySelectorAll('.nav-btn').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(view==='daily')renderDaily();if(view==='progress')renderProgress()}
