    document.querySelectorAll('.cup').forEach(b=>{const filled=Number(b.dataset.cup)<=value.water;b.classList.toggle('filled',filled);b.setAttribute('aria-pressed',String(filled));b.disabled=!ready});
    $('#daily-reset').disabled=!ready;$('#daily-date').textContent=`Today · ${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}`;
