  function renderFlash(){const card=cards[flashOrder[flashIndex]];$('#flash-flip').classList.remove('flipped');$('#flash-flip').setAttribute('aria-pressed','false');$('#flash-position').textContent=`Card ${flashIndex+1} of ${cards.length}`;$('#flash-front-text').textContent=card.front;$('#flash-back-text').textContent=card.back;renderFlashStatus()}
