    $('#quiz-explanation').classList.add('hidden-force');$('#quiz-next').classList.add('hidden-force');
  }
  function answerQuestion(choice){if(answered)return;answered=true;const q=questions[quizIndex];if(choice===q.answer)quizScore++;else missed.push(q);[...$('#quiz-options').children].forEach((b,i)=>{b.disabled=true;if(i===q.answer)b.classList.add('correct');else if(i===choice)b.classList.add('wrong')});$('#quiz-explanation').textContent=(choice===q.answer?'Correct. ':'Not quite. ')+q.why;$('#quiz-explanation').classList.remove('hidden-force');$('#quiz-next').classList.remove('hidden-force');$('#quiz-next-standard').classList.toggle('hidden-force',quizIndex===questions.length-1);$('#quiz-next-final').classList.toggle('hidden-force',quizIndex!==questions.length-1)}
  async function finishQuiz(button){if(!ready||atLimit())return;const ok=await mutation('create',{type:'quiz',score:quizScore,total:questions.length,quiz_date:new Date().toISOString()},button,'Quiz score saved.');if(!ok)return;logStudy();$('#quiz-play').classList.add('hidden-force');$('#quiz-result').classList.remove('hidden-force');$('#quiz-result-score').textContent=`${quizScore} of ${questions.length} correct · ${Math.round(quizScore/questions.length*100)}%`;$('#missed-list').replaceChildren();if(!missed.length){const p=document.createElement('p');p.textContent='No missed questions — well done!';$('#missed-list').append(p)}missed.forEach(q=>{const p=document.createElement('p');p.className='review-item p-3 rounded-xl';p.textContent=`${q.q} — ${q.options[q.answer]}. ${q.why}`;$('#missed-list').append(p)})}
  async function logStudy(){if(streakBusy)return;const date=today(),old=records.find(r=>r.type==='streak');if(old?.last_study_date===date||(!old&&records.length>=999))return;streakBusy=true;try{const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);const prev=`${yesterday.getFullYear()}-${String(yesterday.getMonth()+1).padStart(2,'0')}-${String(yesterday.getDate()).padStart(2,'0')}`;const count=old?.last_study_date===prev?(old.streak||0)+1:1;const result=await window.dataSdk[old?'update':'create'](old?{...old,streak:count,last_study_date:date}:{type:'streak',streak:count,last_study_date:date});if(!result.isOk)message('Your study action saved, but the streak could not be confirmed.',true)}catch{message('Your streak could not be confirmed.',true)}finally{streakBusy=false}}
