  $('#topic-search').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();let n=0;document.querySelectorAll('.topic-card').forEach(c=>{const match=c.dataset.search.includes(q)||c.textContent.toLowerCase().includes(q);c.classList.toggle('hidden-force',!match);if(match)n++});$('#search-empty').classList.toggle('hidden-force',n>0)});
  document.querySelectorAll('.complete-btn').forEach(b=>b.addEventListener('click',async e=>{if(!ready){message('Wait for your progress to load before saving.',true);return}if(atLimit())return;const ok=await mutation('create',{type:'module',module_id:e.currentTarget.dataset.module,completed:true},e.currentTarget,'Module marked complete.');if(ok)logStudy()}));
  $('#flash-flip').addEventListener('click',e=>{const on=e.currentTarget.classList.toggle('flipped');e.currentTarget.setAttribute('aria-pressed',String(on))});
  $('#flash-prev').addEventListener('click',()=>{flashIndex=(flashIndex-1+cards.length)%cards.length;renderFlash()});$('#flash-next').addEventListener('click',()=>{flashIndex=(flashIndex+1)%cards.length;renderFlash()});
  $('#flash-shuffle').addEventListener('click',()=>{for(let i=flashOrder.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[flashOrder[i],flashOrder[j]]=[flashOrder[j],flashOrder[i]]}flashIndex=0;renderFlash();message('Flashcards shuffled.')});
  $('#flash-known').addEventListener('click',async e=>{if(!ready){message('Wait for your progress to load before saving.',true);return}const card=cards[flashOrder[flashIndex]],old=row('flashcard','card_id',card.id);if(!old&&atLimit())return;const known=!old?.known;const ok=await mutation(old?'update':'create',old?{...old,known}:{type:'flashcard',card_id:card.id,known},e.currentTarget,known?'Flashcard marked known.':'Flashcard marked unknown.');if(ok)logStudy()});
  $('#quiz-next').addEventListener('click',e=>{if(quizIndex===questions.length-1)finishQuiz(e.currentTarget);else{quizIndex++;renderQuestion()}});$('#quiz-restart').addEventListener('click',()=>{quizIndex=0;quizScore=0;missed=[];$('#quiz-result').classList.add('hidden-force');$('#quiz-play').classList.remove('hidden-force');renderQuestion()});
  $('#note-form').addEventListener('submit',async e=>{e.preventDefault();if(!ready){message('Wait for your notes to load before saving.',true);return}const text=$('#note-body').value.trim();if(!text){message('Write a note before saving.',true);return}const old=noteEdit?records.find(r=>String(r.__backendId)===noteEdit):null;if(noteEdit&&!old){message('That note is no longer available.',true);return}if(!old&&atLimit())return;const payload=old?{...old,topic_id:$('#note-topic').value,note_text:text}:{type:'note',topic_id:$('#note-topic').value,note_text:text,quiz_date:new Date().toISOString()};const ok=await mutation(old?'update':'create',payload,$('#note-submit'),old?'Note updated.':'Note saved.');if(ok){cancelNote();logStudy()}});
  $('#note-cancel').addEventListener('click',cancelNote);
  $('#notes-list').addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;const el=button.closest('[data-record-id]'),item=records.find(r=>String(r.__backendId)===el.dataset.recordId);if(!item){message('That note is no longer available.',true);return}if(button.classList.contains('edit-note')){noteEdit=String(item.__backendId);$('#note-topic').value=item.topic_id;$('#note-body').value=item.note_text||'';$('#note-cancel').classList.remove('hidden-force');$('#note-body').focus()}else if(button.classList.contains('delete-note'))confirmation(el,'note',true);else if(button.classList.contains('keep-note'))confirmation(el,'note',false);else if(button.classList.contains('confirm-note')){const ok=await mutation('delete',item,button,'Note deleted.');confirmation(el,'note',false);if(ok){el.remove();if(noteEdit===String(item.__backendId))cancelNote()}}});
  $('#bp-form').addEventListener('submit',async e=>{e.preventDefault();if(!ready){message('Wait for your readings to load before saving.',true);return}const old=bpEdit?records.find(r=>String(r.__backendId)===bpEdit):null;if(bpEdit&&!old){message('That reading is no longer available.',true);return}if(!old&&atLimit())return;const date=new Date($('#bp-date').value);if(Number.isNaN(date.getTime())){message('Enter a valid date and time.',true);return}const fields={systolic:Number($('#bp-systolic').value),diastolic:Number($('#bp-diastolic').value),pulse:Number($('#bp-pulse').value),bp_date:date.toISOString(),bp_notes:$('#bp-notes').value.trim()};const ok=await mutation(old?'update':'create',old?{...old,...fields}:{type:'bp',...fields},$('#bp-save'),old?'Reading updated.':'Reading saved.');if(ok)cancelBP()});
  $('#bp-cancel').addEventListener('click',cancelBP);
  $('#bp-list').addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;const el=button.closest('[data-record-id]'),item=records.find(r=>String(r.__backendId)===el.dataset.recordId);if(!item){message('That reading is no longer available.',true);return}if(button.classList.contains('edit-bp')){bpEdit=String(item.__backendId);$('#bp-systolic').value=item.systolic;$('#bp-diastolic').value=item.diastolic;$('#bp-pulse').value=item.pulse;const date=new Date(item.bp_date);const local=new Date(date.getTime()-date.getTimezoneOffset()*60000);$('#bp-date').value=local.toISOString().slice(0,16);$('#bp-notes').value=item.bp_notes||'';$('#bp-cancel').classList.remove('hidden-force');$('#bp-systolic').focus()}else if(button.classList.contains('delete-bp'))confirmation(el,'bp',true);else if(button.classList.contains('keep-bp'))confirmation(el,'bp',false);else if(button.classList.contains('confirm-bp')){const ok=await mutation('delete',item,button,'Reading deleted.');confirmation(el,'bp',false);if(ok){el.remove();if(bpEdit===String(item.__backendId))cancelBP()}}});
  lucide.createIcons();renderFlash();renderQuestion();renderDaily();initialize();
})();
</script>
 
</body>
</html>